function anUnits(mysqli $db,array $p): array {
    $inventory=loadUnitInventory();$owned=[];foreach(anQuery($db,"SELECT DISTINCT unit_number FROM users WHERE role='resident' AND status='approved' AND (account_type IS NULL OR TRIM(account_type)='' OR LOWER(TRIM(account_type))='resident owner') AND unit_number IS NOT NULL")->get_result()as$r)$owned[normalizeUnitNumber($r['unit_number'])]=true;
    $unique=[];$floors=[];$occupied=0;foreach($inventory as$r){$unit=normalizeUnitNumber($r['unit_number']);if(isset($unique[$unit]))continue;$unique[$unit]=true;$occupied+=isset($owned[$unit])?1:0;$floor='Floor '.(int)$r['floor'];$floors[$floor]=($floors[$floor]??0)+1;}uksort($floors,static fn($a,$b)=>(int)substr($a,6)<=>(int)substr($b,6));$total=count($unique);$vacant=$total-$occupied;$url=anLink('superadmin/units.php');
    $metrics=[anMetric('total','Total condominium units',$total?:null,'count','Current inventory','Unique normalized units from the same CSV inventory used by Unit Monitoring.',$url),anMetric('occupied','Occupied units',$total?$occupied:null,'count','Current live status','Approved owner assignment, matching existing Unit Monitoring rules.',anLink('superadmin/units.php',['status'=>'occupied'])),anMetric('vacant','Vacant units',$total?$vacant:null,'count','Current live status','Inventory units without an approved owner assignment.',anLink('superadmin/units.php',['status'=>'vacant'])),anMetric('occupancy','Occupancy rate',anRatio($occupied,$total),'percent','Current live status','Occupied units / actual unique inventory units.'),anMetric('vacancy','Vacancy rate',anRatio($vacant,$total),'percent','Current live status'),anMetric('reserved','Reserved units',null,'count','Unavailable','No reserved unit status is stored by Unit Monitoring.')];
    $rows=[];foreach($floors as$floor=>$count)$rows[]=['label'=>$floor,'value'=>$count,'url'=>anLink('superadmin/units.php')];
    return anSection('units',$metrics,$inventory?[anChart('occupancy','Current occupancy',[['label'=>'Occupied','value'=>$occupied,'url'=>anLink('superadmin/units.php',['status'=>'occupied'])],['label'=>'Vacant','value'=>$vacant,'url'=>anLink('superadmin/units.php',['status'=>'vacant'])]],'donut'),anChart('floors','Actual inventory by floor',$rows)]:[],['The project inventory is a CSV used by the existing Unit Monitoring module, not a units database table. No project unit count is hardcoded.','Historical occupancy and reserved status are unavailable because no complete occupancy snapshot history is recorded. Current assignment counts do not imply physical presence.',!$inventory?'Unit inventory is unavailable. Counts/rates have not been assumed.':'Inventory loaded from the existing project source.']);
}
function anParking(mysqli $db,array $p): array {
    $b=anBounds($p);$u=anBounds($p,true);$prev=anBounds($p,false,true);$prevU=anBounds($p,true,true);$url=anLink('superadmin/parking.php',['tab'=>'visitors']);
    $entries=anNumber($db,'SELECT COUNT(*) FROM visitor_logs WHERE time_in>=? AND time_in<?',$b);$exits=anNumber($db,'SELECT COUNT(*) FROM visitor_logs WHERE time_out>=? AND time_out<?',$b);$prevEntries=anNumber($db,'SELECT COUNT(*) FROM visitor_logs WHERE time_in>=? AND time_in<?',$prev);$people=anNumber($db,'SELECT COALESCE(SUM(visitor_count),0) FROM visitor_logs WHERE time_in>=? AND time_in<?',$b);$active=anRow($db,"SELECT COUNT(*) parties,COALESCE(SUM(visitor_count),0) people FROM visitor_logs WHERE status='checked_in' AND time_out IS NULL");
    $registration=anRow($db,"SELECT COUNT(*) total,COALESCE(SUM(EXISTS(SELECT 1 FROM parking_requests pr WHERE pr.visitor_registration_id=r.id AND pr.request_type='visitor')),0) vehicles FROM resident_service_requests r WHERE r.request_kind='visitor' AND r.created_at>=? AND r.created_at<?",$b);
    $inWhere="request_type='visitor' AND actual_check_in>=? AND actual_check_in<?";$outWhere="request_type='visitor' AND actual_check_out>=? AND actual_check_out<?";
    $sessions=anNumber($db,"SELECT COUNT(*) FROM parking_requests WHERE $inWhere",$u);$completed=anNumber($db,"SELECT COUNT(*) FROM parking_requests WHERE $outWhere",$u);$free=anNumber($db,"SELECT COUNT(*) FROM parking_requests WHERE $outWhere AND fee_state='free' AND JSON_EXTRACT(calculation_snapshot,'$.grace_applied')=true",$u);
    $parkLive=anRow($db,"SELECT COALESCE(SUM(actual_check_in IS NOT NULL AND actual_check_out IS NULL),0) active,COALESCE(SUM(fee_state IN ('pending_rate_review','pending_account_review')),0) reviews,COALESCE(SUM(actual_check_in IS NOT NULL AND actual_check_out IS NULL AND parking_compliance IN ('unapproved_extended','overstayed_approved')),0) unapproved FROM parking_requests WHERE request_type='visitor'");
    $slot=anRow($db,"SELECT COUNT(*) total,COALESCE(SUM(status='occupied'),0) occupied,COALESCE(SUM(status='available' AND assigned_user_id IS NULL),0) available,COALESCE(SUM(status='available' AND assigned_user_id IS NOT NULL),0) reserved,COALESCE(SUM(status='maintenance'),0) maintenance FROM parking_slots WHERE slot_type='visitor'");
    $financial=anRow($db,"SELECT COALESCE(ROUND(SUM(IF(p.status='paid' AND p.paid_at>=? AND p.paid_at<?,p.amount,0))*100),0) collected,COALESCE(SUM(p.status='paid' AND p.paid_at>=? AND p.paid_at<?),0) paid,COALESCE(ROUND(SUM(IF(p.status IN ('pending','overdue'),p.amount,0))*100),0) outstanding FROM parking_requests pr JOIN payments p ON p.id=pr.payment_id WHERE pr.request_type='visitor' AND pr.actual_check_out IS NOT NULL AND pr.fee_state NOT IN ('free','pending_rate_review','pending_account_review') AND p.amount>0",array_merge($b,$b));
    $billed=anNumber($db,"SELECT COALESCE(ROUND(SUM(pr.parking_fee)*100),0) FROM parking_requests pr JOIN payments p ON p.id=pr.payment_id WHERE pr.request_type='visitor' AND pr.actual_check_out IS NOT NULL AND pr.fee_state NOT IN ('free','pending_rate_review','pending_account_review') AND p.amount>0 AND p.status IN ('paid','pending','overdue') AND COALESCE(pr.rate_reviewed_at,pr.actual_check_out)>=? AND COALESCE(pr.rate_reviewed_at,pr.actual_check_out)<?",$u);
    $overnight=anNumber($db,"SELECT COUNT(*) FROM parking_requests WHERE $outWhere AND fee_state NOT IN ('pending_rate_review','pending_account_review') AND COALESCE(JSON_EXTRACT(calculation_snapshot,'$.overnight_cents'),0)>0",$u);$extended=anNumber($db,"SELECT COUNT(*) FROM parking_requests WHERE $inWhere AND TIMESTAMPDIFF(SECOND,actual_check_in,COALESCE(actual_check_out,UTC_TIMESTAMP(6)))>86400",$u);
    $average=anRow($db,"SELECT AVG(TIMESTAMPDIFF(SECOND,actual_check_in,actual_check_out)) average_seconds FROM parking_requests WHERE $outWhere AND actual_check_out>=actual_check_in",$u)['average_seconds'];
    $metrics=[anMetric('registrations','Visitor registrations',(int)$registration['total'],'count','Created during selected period'),anMetric('unique_visitors','Unique visitors',null,'count','Unavailable','Names/contacts are not stable verified visitor identifiers.'),anMetric('entries','Confirmed visitor entries',$entries,'count','Entry time in selected period','Visitor log records represent visit parties; scans/registrations are not entries.',anLink('superadmin/visitorlog.php'),$prevEntries),anMetric('entered_people','People in confirmed entries',$people,'count','Entry time in selected period','Sum of recorded visitor_count; not unique people.'),anMetric('exits','Confirmed visitor exits',$exits),anMetric('active_visitors','Visitors currently inside',(int)$active['parties'],'count','Current live visit parties','People currently inside: '.$active['people'].'.',anLink('superadmin/visitorlog.php')),anMetric('sessions','Vehicle sessions started',$sessions,'count','Actual entry in selected period','Approved reservations without actual entry are excluded.',$url,anNumber($db,"SELECT COUNT(*) FROM parking_requests WHERE $inWhere",$prevU)),anMetric('active_vehicles','Active visitor vehicles',(int)$parkLive['active'],'count','Current live parking','Actual entry recorded; actual checkout not yet recorded.',$url),anMetric('completed','Completed parking sessions',$completed,'count','Actual checkout in selected period'),anMetric('free','Free grace-period checkouts',$free,'count','Checkout in selected period','Uses finalized calculator snapshot, never a recalculated estimate.'),anMetric('paid_sessions','Parking invoices settled',(int)$financial['paid'],'count','Payment date in selected period'),anMetric('billed','Finalized parking charges',$billed,'money','Charge finalization in selected period'),anMetric('collected','Parking payments collected',(int)$financial['collected'],'money','Payment date in selected period'),anMetric('outstanding','Outstanding parking charges',(int)$financial['outstanding'],'money','Current live balance'),anMetric('overnight','Qualifying overnight checkouts',$overnight,'count','Checkout in selected period','Positive overnight component in confirmed stored calculation.'),anMetric('extended','Extended entry-cohort sessions',$extended,'count','Period entries, duration through refresh','Actual continuous duration beyond 24 hours; extension approval is a separate state.'),anMetric('unapproved','Unapproved active extended stays',(int)$parkLive['unapproved'],'count','Current recorded compliance','Read-only snapshot of stored monitoring state.',$url),anMetric('reviews','Unresolved rate/account reviews',(int)$parkLive['reviews'],'count','Current live review queue'),anMetric('average_duration','Average completed parking duration',$average!==null?round((float)$average/3600,2):null,'hours','Checkout in selected period','Only nonnegative recorded actual entry/exit durations.'),anMetric('slots','Visitor parking slots',(int)$slot['total'],'count','Current inventory'),anMetric('slot_occupancy','Visitor slot occupancy',anRatio((int)$slot['occupied'],(int)$slot['total']),'percent','Current recorded inventory','Occupied visitor slots / total visitor slots, including out-of-service capacity.'),anMetric('available_slots','Available visitor slots',(int)$slot['available'],'count','Current inventory')];
    $cols=anTrend($db,'parking_requests pr JOIN payments p ON p.id=pr.payment_id','p.paid_at',"pr.request_type='visitor' AND pr.actual_check_out IS NOT NULL AND pr.fee_state NOT IN ('free','pending_rate_review','pending_account_review') AND p.amount>0 AND p.status='paid' AND p.paid_at>=? AND p.paid_at<?",$b,$p,'COALESCE(ROUND(SUM(p.amount)*100),0)');
    $duration="CASE WHEN TIMESTAMPDIFF(SECOND,actual_check_in,actual_check_out)<=900 THEN '0-15 minutes' WHEN TIMESTAMPDIFF(SECOND,actual_check_in,actual_check_out)<=10800 THEN '15 minutes-3 hours' WHEN TIMESTAMPDIFF(SECOND,actual_check_in,actual_check_out)<=86400 THEN '3-24 hours' ELSE 'More than 24 hours' END";
    return anSection('parking',$metrics,[anChart('visitor_entries','Confirmed visitor entries',anTrend($db,'visitor_logs','time_in','time_in>=? AND time_in<?',$b,$p),'line'),anChart('visitor_status','Current status of period registrations',anGroup($db,'resident_service_requests','status',"request_kind='visitor' AND created_at>=? AND created_at<?",$b),'donut'),anChart('vehicles','Period registrations with parking requests',[['label'=>'With parking request','value'=>(int)$registration['vehicles']],['label'=>'Without parking request','value'=>(int)$registration['total']-(int)$registration['vehicles']]],'donut'),anChart('entry_hours','Confirmed visitor entries by Philippine hour',anGroup($db,'visitor_logs',"LPAD(HOUR(time_in),2,'0')",'time_in>=? AND time_in<?',$b)),anChart('parking_entries','Actual vehicle entries',anTrend($db,'parking_requests','actual_check_in',$inWhere,$u,$p,'COUNT(*)',true),'line'),anChart('parking_collections','Verified parking collections',$cols,'line','money'),anChart('durations','Completed actual parking durations',anGroup($db,'parking_requests',$duration,$outWhere.' AND actual_check_out>=actual_check_in',$u)),anChart('slots','Current visitor slot inventory',[['label'=>'Occupied','value'=>$slot['occupied']],['label'=>'Available','value'=>$slot['available']],['label'=>'Reserved assignment','value'=>$slot['reserved']],['label'=>'Out of service','value'=>$slot['maintenance']]],'donut'),anChart('parking_outcomes','Completed session billing outcomes',anGroup($db,'parking_requests','fee_state',$outWhere,$u),'donut'),anChart('overnight_trend','Confirmed overnight checkout frequency',anTrend($db,'parking_requests','actual_check_out',$outWhere." AND fee_state NOT IN ('pending_rate_review','pending_account_review') AND COALESCE(JSON_EXTRACT(calculation_snapshot,'$.overnight_cents'),0)>0",$u,$p,'COUNT(*)',true),'line')],['Parking money uses finalized snapshots and uniquely linked invoices. No parking pricing logic is recreated here. Unresolved reviews/free sessions are excluded from bill/collection totals.','Visitor registration, confirmed visit-party entries, people counts and actual vehicle movements are distinct measures. Stable visitor identity is not available for unique-person counting.','Current compliance is the stored monitoring state; Analytics does not run monitoring or repair inventory. Duration buckets describe time only, not fee calculations.']);
}
function anMaintenance(mysqli $db,array $p): array {
    $b=anBounds($p);$where='created_at>=? AND created_at<?';$row=anRow($db,"SELECT COUNT(*) total,COALESCE(SUM(status='pending'),0) pending,COALESCE(SUM(status='in_progress'),0) in_progress,COALESCE(SUM(status='completed'),0) completed,COALESCE(SUM(status='closed'),0) closed,COALESCE(SUM(status IN ('rejected','cancelled')),0) declined FROM maintenance_requests WHERE $where",$b);$open=anNumber($db,"SELECT COUNT(*) FROM maintenance_requests WHERE status IN ('pending','approved','in_progress','reopened')");$url=anLink('superadmin/maintenancerequests.php');$metrics=[anMetric('total','New maintenance requests',(int)$row['total'],'count','Created during selected period','Current status of the selected creation cohort.',$url,anNumber($db,"SELECT COUNT(*) FROM maintenance_requests WHERE $where",anBounds($p,false,true))),anMetric('open','Unresolved maintenance requests',$open,'count','Current live backlog','Pending, approved, in progress or reopened; no invented SLA/overdue flag.',$url),anMetric('pending','Pending cohort requests',(int)$row['pending'],'count','Period creation cohort','Current status.',anLink('superadmin/maintenancerequests.php',['status'=>'pending'])),anMetric('in_progress','In progress cohort requests',(int)$row['in_progress']),anMetric('completed','Completed cohort requests',(int)$row['completed']),anMetric('closed','Closed cohort requests',(int)$row['closed']),anMetric('declined','Rejected/cancelled cohort requests',(int)$row['declined']),anMetric('completion_rate','Cohort resolution rate',anRatio((int)$row['completed']+(int)$row['closed'],(int)$row['total']),'percent','Period creation cohort, current status'),anMetric('resolution_time','Average resolution time',null,'hours','Unavailable','No immutable completion timestamp; updated_at may change after completion.')];
    $status=anGroup($db,'maintenance_requests','status',$where,$b);foreach($status as&$r)$r['url']=anLink('superadmin/maintenancerequests.php',['status'=>$r['label']]);unset($r);
    return anSection('maintenance',$metrics,[anChart('maintenance_trend','New maintenance requests',anTrend($db,'maintenance_requests','created_at',$where,$b,$p),'line'),anChart('maintenance_status','Current cohort request status',$status,'donut'),anChart('maintenance_categories','Requests by actual category',anGroup($db,'maintenance_requests','issue_type',$where,$b)),anChart('maintenance_resolved','Resolved vs other cohort requests',[['label'=>'Completed / closed','value'=>(int)$row['completed']+(int)$row['closed']],['label'=>'Other current statuses','value'=>(int)$row['total']-(int)$row['completed']-(int)$row['closed']]],'donut')],['Completion-event trends and resolution time by category are unavailable: updated_at is not a reliable completion timestamp. Cohort status charts do not pretend to show historical completion dates.','No approved SLA/expected completion deadline exists, so unresolved requests are not labeled overdue.']);
}
function anAmenities(mysqli $db,array $p): array {
    $b=anBounds($p);$w='created_at>=? AND created_at<?';$r=anRow($db,"SELECT COUNT(*) total,COALESCE(SUM(status IN ('approved','confirmed')),0) approved,COALESCE(SUM(status='pending'),0) pending,COALESCE(SUM(status='rejected'),0) rejected,COALESCE(SUM(status='cancelled'),0) cancelled,COALESCE(SUM(status='completed'),0) completed FROM bookings WHERE $w",$b);$url=anLink('superadmin/bookingrequest.php');$m=[];foreach(['total'=>'Amenity reservations created','approved'=>'Approved / confirmed cohort bookings','pending'=>'Pending cohort bookings','rejected'=>'Rejected cohort bookings','cancelled'=>'Cancelled cohort bookings','completed'=>'Completed cohort bookings']as$key=>$label)$m[]=anMetric($key,$label,(int)$r[$key],'count','Period creation cohort','Current stored status of requests created in the period.',$url,$key==='total'?anNumber($db,"SELECT COUNT(*) FROM bookings WHERE $w",anBounds($p,false,true)):null);$m[]=anMetric('utilization','Physical facility utilization',null,'percent','Unavailable','No capacity/calendar history or actual facility entry/exit ledger exists.');
    $statuses=anGroup($db,'bookings','status',$w,$b);foreach($statuses as&$row)$row['url']=anLink('superadmin/bookingrequest.php',['status'=>$row['label']]);unset($row);$scheduled='booking_date>=? AND booking_date<=? AND status IN (\'approved\',\'confirmed\',\'completed\')';$dates=[$p['start'],min($p['end'],substr($p['until'],0,10))];
    return anSection('amenities',$m,[anChart('bookings_by_amenity','Reservations by actual amenity',anGroup($db,'bookings','amenity',$w,$b)),anChart('booking_trend','New reservation trend',anTrend($db,'bookings','created_at',$w,$b,$p),'line'),anChart('booking_status','Current reservation status',$statuses,'donut'),anChart('booking_weekday','Approved/confirmed scheduled bookings by weekday',anGroup($db,'bookings','DAYNAME(booking_date)',$scheduled,$dates)),anChart('scheduled_amenities','Approved/confirmed/completed reservations on period dates',anGroup($db,'bookings','amenity',$scheduled,$dates))],['Reservation creation trends and scheduled reservation dates are different measures. Rejected/cancelled requests are excluded from scheduled-use counts.','Actual facility attendance and utilization percentages are unavailable; an approved reservation is not proof of physical use.']);
}
function anViolations(mysqli $db,array $p): array {
    $b=anBounds($p);$confirmed="review_status IN ('legacy','approved') AND status IS NOT NULL";$issued="CASE WHEN review_status='approved' THEN reviewed_at ELSE created_at END";$w="($issued)>=? AND ($issued)<?";$r=anRow($db,"SELECT COALESCE(SUM($confirmed),0) total,COALESCE(SUM(review_status='pending'),0) pending_review,COALESCE(SUM(($confirmed) AND status IN ('paid','waived','warning_issued')),0) resolved,COALESCE(SUM(($confirmed) AND status='disputed'),0) disputed FROM violations WHERE $w",$b);
    $money=anRow($db,"SELECT COALESCE(ROUND(SUM(IF(p.status IN ('pending','overdue'),bi.amount,0))*100),0) outstanding,COALESCE(ROUND(SUM(IF(p.status='paid' AND p.paid_at>=? AND p.paid_at<?,bi.amount,0))*100),0) collected FROM bill_items bi JOIN payments p ON p.id=bi.payment_id JOIN (SELECT payment_id,SUM(amount) total FROM bill_items GROUP BY payment_id) reconciled ON reconciled.payment_id=p.id AND reconciled.total=p.amount WHERE EXISTS(SELECT 1 FROM violations v WHERE v.bill_item_id=bi.id AND v.payment_id=p.id AND v.review_status IN ('legacy','approved') AND v.status IS NOT NULL)",$b);
    $url=anLink('superadmin/violations.php',['tab'=>'history']);$m=[anMetric('total','Confirmed violations issued',(int)$r['total'],'count','Recorded issuance date in selected period','Approved review timestamp, or original legacy issuance date; pending/rejected allegations excluded.',$url,anNumber($db,"SELECT COUNT(*) FROM violations WHERE $w AND $confirmed",anBounds($p,false,true))),anMetric('pending_review','Pending allegation reviews',(int)$r['pending_review'],'count','Period creation cohort','Not confirmed violations.'),anMetric('resolved','Warning / paid / waived cohort records',(int)$r['resolved'],'count','Period issuance cohort, current status'),anMetric('disputed','Disputed cohort records',(int)$r['disputed']),anMetric('outstanding','Unpaid linked violation charges',(int)$money['outstanding'],'money','Current live balance','Count each linked bill item once, even when several fines share an invoice.'),anMetric('collected','Verified violation payments',(int)$money['collected'],'money','Payment date in selected period','Allocated linked bill items; unlinked historical fines are not treated as collections.'),anMetric('repeat_accounts','Responsible accounts with repeated records',anNumber($db,"SELECT COUNT(*) FROM (SELECT user_id FROM violations WHERE $w AND $confirmed AND user_id IS NOT NULL GROUP BY user_id HAVING COUNT(*)>1) repeat_accounts",$b),'count','Confirmed period issuance records','Responsible billing accounts, not a ranking or proof of the same individual offender.')];
    return anSection('violations',$m,[anChart('violation_trend','Confirmed violations issued',anTrend($db,'violations',$issued,"$w AND $confirmed",$b,$p),'line'),anChart('violation_categories','Actual confirmed violation categories',anGroup($db,'violations','violation_type',"$w AND $confirmed",$b)),anChart('violation_status','Current confirmed violation status',anGroup($db,'violations','status',"$w AND $confirmed",$b),'donut'),anChart('violation_money','Violation charges: different time bases',[['label'=>'Current unpaid linked charges','value'=>(int)$money['outstanding']],['label'=>'Verified collections in period','value'=>(int)$money['collected']]],'bar','money')],['Pending complaints and rejected reports are excluded from confirmed violation totals. No resident names, evidence or repeat-offender ranking is exposed. Repeated responsible-account records do not establish individual offender identity.','Money is allocated once per real linked bill item on a reconciled invoice. Mismatched invoice items, unlinked legacy fines and approved reports missing a review timestamp are data-quality limitations, not inferred transactions/dates.']);
}
